INSERT INTO Prospect (AgencyID, SK_RecordDateID, SK_UpdateDateID, BatchID, IsCustomer, LastName, FirstName, MiddleInitial, Gender, AddressLine1, AddressLine2, PostalCode, City, State, Country, Phone, Income, numberCars, numberChildren, MaritalStatus, Age, CreditRating, OwnOrRentFlag, Employer, numberCreditCards, NetWorth, MarketingNameplate) SELECT AgencyID, (SELECT SK_DateID FROM DimDate WHERE DateValue = (SELECT BatchDate FROM Source.BatchDate)) AS SK_RecordDateID, (SELECT SK_DateID FROM DimDate WHERE DateValue = (SELECT BatchDate FROM Source.BatchDate)) AS SK_UpdateDateID, 1 AS BatchID, (SELECT COUNT(*) > 0 FROM DimCustomer AS DC WHERE DC.IsCurrent = TRUE AND DC.Status = 'Active' AND UPPER(DC.FirstName) = UPPER(TRIM(P.FirstName)) AND UPPER(DC.LastName) = UPPER(TRIM(P.LastName)) AND UPPER(DC.AddressLine1) = UPPER(TRIM(P.AddressLine1)) AND UPPER(COALESCE(DC.AddressLine2, '')) = UPPER(COALESCE(TRIM(P.AddressLine2), '')) AND UPPER(DC.PostalCode) = UPPER(TRIM(P.PostalCode))) AS IsCustomer, LastName, FirstName, MiddleInitial, Gender, AddressLine1, AddressLine2, PostalCode, City, State, Country, Phone, Income, numberCars, numberChildren, MaritalStatus, Age, CreditRating, OwnOrRentFlag, Employer, numberCreditCards, NetWorth, NULLIF(CONCAT_WS('+', CASE WHEN NetWorth > 1000000 OR Income > 200000 THEN 'HighValue' END, CASE WHEN NumberChildren > 3 OR NumberCreditCards > 5 THEN 'Expenses' END, CASE WHEN Age > 45 THEN 'Boomer' END, CASE WHEN Income < 50000 OR CreditRating < 600 OR NetWorth < 100000 THEN 'MoneyAlert' END, CASE WHEN NumberCars > 3 OR NumberCreditCards > 7 THEN 'Spender' END, CASE WHEN Age < 25 AND NetWorth > 1000000 THEN 'Inherited' END), '') AS MarketingNameplate FROM Source.Prospect AS P